 family=spec['family'];task=spec['task'];split=spec['split'];hook=spec['representation'];seed=spec['CV_seed'];key='final_norm' if hook=='decoder.final_norm' else hook.replace('decoder.layers.','decoder_layer_');uid=f'{task}/{split}/{key}/seed{seed}';root=A/'contrasts/classifier'/family/uid;source=contrast_source();tmp=None
